"""Migrated Meridian CRM 4.2 order_fulfilment workflow."""

from typing import Any


def _numeric(value: Any) -> float:
    """Apply legacy empty-string numeric coercion."""
    if value is None or value == "":
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def _account_credit_hold(record: dict, tables: dict) -> str:
    """Implement legacy LOOKUP over the first live ACCT_MASTER row."""
    account_id = record.get("ACCT_ID", "")
    for row in tables.get("ACCT_MASTER", []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get("ACCT_ID", "") == account_id:
            return row.get("CRED_HOLD", "")
    return ""


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    """Fire one order_fulfilment workflow event using legacy transition semantics."""
    result_record = dict(record)

    transitions = (
        ("E", "approve", "A", lambda: _numeric(record.get("TOT_AMT", "")) > 0,
         ("ORD_APPR",), ()),
        ("A", "ship", "S", lambda: True,
         ("ORD_SHIP",), ("shipped",)),
        ("S", "invoice", "I", lambda: True,
         ("ORD_INV",), ()),
        ("E", "cancel", "X", lambda: True,
         ("ORD_CANC",), ()),
        ("A", "cancel", "X",
         lambda: _account_credit_hold(record, tables) != "Y",
         ("ORD_CANC",), ()),
        ("I", "cancel", "X", lambda: True,
         ("ORD_CANC_INV",), ("credit_note",)),
    )

    for from_state, transition_event, to_state, guard, audits, notifies in transitions:
        if state == from_state and event == transition_event and guard():
            return {
                "state": to_state,
                "record": result_record,
                "audits": list(audits),
                "notifies": list(notifies),
                "matched": True,
            }

    return {
        "state": state,
        "record": result_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
